'use client';

import { useEffect, useState, use } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import Navbar from '@/components/landing/Navbar';
import Footer from '@/components/landing/Footer';
import { ChevronLeft, ShoppingCart, CreditCard } from 'lucide-react';
import styles from './MenuDetail.module.css';

interface MenuDetail {
    id: number;
    korName: string;
    engName: string;
    description: string;
    price: number;
    categoryName: string;
    imagesSrc: string;
}

type Params = Promise<{ id: string }>;

export default function MenuDetailPage({ params }: { params: Params }) {
    const { id } = use(params);
    const router = useRouter();

    const [menu, setMenu] = useState<MenuDetail | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(false);

    useEffect(() => {
        const fetchMenuDetail = async () => {
            try {
                const res = await fetch(`/api/menus/${id}`);
                if (res.ok) {
                    const data = await res.json();
                    if (data) {
                        setMenu(data);
                    } else {
                        setError(true);
                    }
                } else {
                    setError(true);
                }
            } catch (err) {
                console.error("Failed to fetch menu detail:", err);
                setError(true);
            } finally {
                setLoading(false);
            }
        };

        fetchMenuDetail();
    }, [id]);

    const formatPrice = (price?: number) => {
        if (price === undefined || price === null) return '';
        return price.toLocaleString('ko-KR') + '원';
    };

    const handleAddToCart = () => {
        alert(`'${menu?.korName}' 카트에 귀엽게 담았습니다! 🐤`);
    };

    const handleOrderNow = () => {
        alert(`'${menu?.korName}' 주문 화면으로 이동합니다! 🚀`);
    };

    if (loading) {
        return (
            <main className={styles.main}>
                <Navbar />
                <div className={styles.contentWrapper}>
                    <div className={styles.emptyState}>메뉴 정보를 불러오는 중입니다... ☕</div>
                </div>
                <Footer />
            </main>
        );
    }

    if (error || !menu) {
        return (
            <main className={styles.main}>
                <Navbar />
                <div className={styles.contentWrapper}>
                    <div className={styles.emptyState}>해당 메뉴를 찾을 수 없습니다 😢</div>
                    <div style={{ textAlign: 'center', marginTop: '20px' }}>
                        <Link href="/menus" className={styles.backLink}>
                            메뉴 목록으로 돌아가기
                        </Link>
                    </div>
                </div>
                <Footer />
            </main>
        );
    }

    return (
        <main className={styles.main}>
            <Navbar />

            <div className={styles.contentWrapper}>
                <Link href="/menus" className={styles.backLink}>
                    <ChevronLeft size={20} />
                    메뉴 목록으로
                </Link>

                <div className={styles.grid}>
                    {/* 왼쪽: 상품 이미지 */}
                    <div className={styles.leftColumn}>
                        <div className={styles.imageContainer}>
                            <img
                                src={`/images/${menu.imagesSrc || 'blank.png'}`}
                                alt={menu.korName}
                                className={styles.image}
                                onError={(e) => {
                                    (e.target as HTMLImageElement).src = '/images/blank.png';
                                }}
                            />
                        </div>
                    </div>

                    {/* 오른쪽: 상품 정보 및 주문 액션 */}
                    <div className={styles.rightColumn}>
                        <div className={styles.categoryBadge}>{menu.categoryName || '스페셜'}</div>

                        <h1 className={styles.title}>{menu.korName}</h1>
                        {menu.engName && <h2 className={styles.engTitle}>{menu.engName}</h2>}

                        <div className={styles.divider} />

                        <p className={styles.description}>
                            {menu.description || '정말 맛있는 고라파덕 카페의 자랑, 스페셜 메뉴입니다! 한 입 먹으면 기분이 좋아져요.'}
                        </p>

                        <div className={styles.price}>
                            {formatPrice(menu.price)}
                        </div>

                        {/* 주문 액션 버튼들 (사용자 페이지) */}
                        <div className={styles.actionGroup}>
                            <button className={styles.secondaryButton} onClick={handleAddToCart}>
                                <ShoppingCart size={20} />
                                장바구니 담기
                            </button>
                            <button className={styles.primaryButton} onClick={handleOrderNow}>
                                <CreditCard size={20} />
                                바로 주문하기
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            <Footer />
        </main>
    );
}
